INSERT INTO collection_pages VALUES('219253208bce29624a1a096348377b75adf2fe314182b76d599640301bb750a3','3bc574ba688519b593a49fb32a0d689ae89fabbfc16123d4dfc063421d46f736','{"hasNext":false,"items":[{"author":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"authoredDate":"2026-08-29T09:21:17Z","committedDate":"2026-08-29T09:21:17Z","committer":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"observedAt":"2026-10-09T00:25:31.875Z","repositoryId":1349566910,"sha":"433d13a26b224ff2a6f34c9cec0bf1c85a1b120a"},{"author":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"authoredDate":"2026-08-29T09:04:34Z","committedDate":"2026-08-29T09:04:34Z","committer":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"observedAt":"2026-10-09T00:25:31.875Z","repositoryId":1349566910,"sha":"35b969b13a82416156e997989c6bcc8709ba87e7"},{"author":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"authoredDate":"2026-08-29T07:59:16Z","committedDate":"2026-08-29T07:59:16Z","committer":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"observedAt":"2026-10-09T00:25:31.875Z","repositoryId":1349566910,"sha":"77314b542347d82d18f0dd17eda9802212a85ce2"},{"author":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"authoredDate":"2026-08-29T06:59:53Z","committedDate":"2026-08-29T06:59:53Z","committer":{"account":{"login":"ikundanpatil","providerType":"User"},"email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"observedAt":"2026-10-09T00:25:31.875Z","repositoryId":1349566910,"sha":"ce386b641f4319a4d9344a57c084f74d78902dbe"}],"observedAt":"2026-10-09T00:25:31.875Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/433d13a26b224ff2a6f34c9cec0bf1c85a1b120a/comments","commit":{"author":{"date":"2026-08-29T09:21:17Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"comment_count":0,"committer":{"date":"2026-08-29T09:21:17Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"message":"Wire the end-to-end inspection flow (upload → vision → risk → report → dashboard)\n\nNew pipeline (app/services/flow_service.py) ties the pieces together:\n  upload image → Supabase Storage → YOLO (or simulated fallback) → violations\n  in PostgreSQL → Gemini complaint triage → Risk Engine → compliance report\n  → report saved to DB → dashboard reflects it (live reads).\n\nAPIs:\n- POST /api/v1/inspection/upload   (multipart: store_id, images[], complaint_text?,\n  checklist?) — creates the inspection, pushes each image to Supabase Storage,\n  degrades to a warning when Supabase is unconfigured, returns ws_url\n- POST /api/v1/inspection/analyze  — runs the full pipeline; structured JSON with\n  detections, violations_persisted, risk{score,compliance,level,breakdown},\n  complaint_analysis, report{id,reference,status,pending}, warnings[]\n- GET  /api/v1/dashboard/summary   — live KPIs, risk mix, 6-mo compliance trend,\n  today''s inspections, recent alerts (no cache → auto-updates)\n- GET  /api/v1/stores/{id}/risk-history — per-inspection risk/compliance points\n- GET  /api/v1/reports/{id}        — unchanged\n\nAdded:\n- Risk Engine (app/services/risk_service.py): transparent, unit-tested scoring\n  — severity-weighted violations + failed checklist areas + complaint bump\n- Background report generation via FastAPI BackgroundTasks (background_report=true\n  returns a draft placeholder id, finishes async, optional Gemini narrative +\n  Supabase persist)\n- WebSocket live progress: WS /api/v1/ws/inspections/{id}?token=<jwt> streams\n  connected→detecting→complaint→scoring→report→done; WS /api/v1/ws/dashboard\n  emits a refresh ping. In-process fan-out (app/realtime/progress.py), thread-safe\n  publish for the sync pipeline / background tasks.\n- supabase_client.fetch_object_bytes() so the YOLO path can re-read the stored image\n- report_service.ensure_pending() placeholder row for background generation\n\nFrontend UI untouched. 8 new tests (full pipeline, background report, dashboard,\nrisk-history, WS progress + auth, risk math); 36 tests pass, ruff clean.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"873de567e94e21b00d4fb72be2bfa28a662b556b","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/trees/873de567e94e21b00d4fb72be2bfa28a662b556b"},"url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/commits/433d13a26b224ff2a6f34c9cec0bf1c85a1b120a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/433d13a26b224ff2a6f34c9cec0bf1c85a1b120a","node_id":"C_kwDOUHDBvtoAKDQzM2QxM2EyNmIyMjRmZjJhNmYzNGM5Y2VjMGJmMWM4NWExYjEyMGE","parents":[{"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/35b969b13a82416156e997989c6bcc8709ba87e7","sha":"35b969b13a82416156e997989c6bcc8709ba87e7","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/35b969b13a82416156e997989c6bcc8709ba87e7"}],"sha":"433d13a26b224ff2a6f34c9cec0bf1c85a1b120a","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/433d13a26b224ff2a6f34c9cec0bf1c85a1b120a"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/35b969b13a82416156e997989c6bcc8709ba87e7/comments","commit":{"author":{"date":"2026-08-29T09:04:34Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"comment_count":0,"committer":{"date":"2026-08-29T09:04:34Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"message":"Add external integrations, raw SQL bootstrap, and nav-state persistence\n\nBackend — external integrations (app/integrations/, all secrets from .env):\n- gemini_client.py: analyze_complaint() + generate_report() via the Gemini\n  REST generateContent endpoint (httpx, JSON output, retries)\n- supabase_client.py: upload_inspection_image() (Storage) + save_report()\n  (PostgREST), reads SUPABASE_URL / SUPABASE_KEY\n- vision_service.py: local Ultralytics YOLO, NO API key; lazy import, maps\n  detections onto the shared violation catalogue; falls back cleanly when\n  ultralytics/model absent (requirements-vision.txt extra)\n- integration_service.py wires them to the domain; ai.py router gains\n  GET /ai/integrations, POST /ai/complaints/analyze, POST /ai/reports/generate,\n  POST /ai/vision/detect (multipart). Unconfigured -> 503, app still boots.\n- config + .env.example: GEMINI_*, SUPABASE_*, VISION_BACKEND / YOLO_* keys\n- httpx promoted to a runtime dependency\n- ruff clean; 28 tests still pass\n\nBackend — raw SQL (Supabase-first bootstrap, 6 core tables, no ai_analyses):\n- schema.sql: native Postgres DDL (uuid PKs, native enums, jsonb,\n  updated_at trigger), PKs/FKs/CHECKs/indexes for users, stores, inspections,\n  violations, complaints, reports\n- seed.sql: 10 stores across Mumbai / Pune / Nashik + users + demo\n  inspections/violations/complaints/reports; idempotent\n- DATABASE.md explains how these relate to the Alembic-managed schema\n\nFrontend — navigation.tsx: persist the current screen to sessionStorage so a\ndev hot-reload keeps you on the screen you were testing instead of resetting to\nSplash. Fresh tab (the demo) still starts at Splash; ?fgscreen=<name> / =reset\nescape hatches. tsc + rsbuild build pass.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"85117d428def5edd10f938aaf3dece9d443a6376","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/trees/85117d428def5edd10f938aaf3dece9d443a6376"},"url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/commits/35b969b13a82416156e997989c6bcc8709ba87e7","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/35b969b13a82416156e997989c6bcc8709ba87e7","node_id":"C_kwDOUHDBvtoAKDM1Yjk2OWIxM2E4MjQxNjE1NmU5OTc5ODljNmJjYzg3MDliYTg3ZTc","parents":[{"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/77314b542347d82d18f0dd17eda9802212a85ce2","sha":"77314b542347d82d18f0dd17eda9802212a85ce2","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/77314b542347d82d18f0dd17eda9802212a85ce2"}],"sha":"35b969b13a82416156e997989c6bcc8709ba87e7","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/35b969b13a82416156e997989c6bcc8709ba87e7"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/77314b542347d82d18f0dd17eda9802212a85ce2/comments","commit":{"author":{"date":"2026-08-29T07:59:16Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"comment_count":0,"committer":{"date":"2026-08-29T07:59:16Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"message":"Add FastAPI backend for FranchiseGuard AI\n\nStandalone production-ready API (does not depend on the RocketRide platform):\n\n- FastAPI + SQLAlchemy 2.0 (sync) + Alembic + Pydantic v2, PostgreSQL/Supabase\n- JWT auth (access + refresh, PyJWT + bcrypt), OAuth2 password grant\n- 4 roles: admin / area_manager / inspector / franchise_owner, enforced via\n  require_roles dependency; franchise_owner rows are ownership-scoped\n- Routers: auth, stores, inspections, violations, complaints, reports, ai\n- Domain aligned with the frontend: 15 stores, 10-item violation catalogue,\n  5 checklist areas\n- Pluggable AI engine (app/services/ai): SimulatedVisionEngine (deterministic,\n  seeded, port of frontend src/lib/ai.ts) + RemoteVisionEngine stub for a real\n  model / RocketRide vision pipeline; every run persisted as AIAnalysis\n- Full flow: inspection -> AI analyze -> violations -> compliance report ->\n  ReportLab PDF -> share link\n- GET /health (liveness + DB probe), Swagger at /docs, request-id logging\n  middleware, stable JSON error envelope\n- Alembic initial migration (portable GUID type), env wired to app settings\n- Seed script (admin + demo data via the real analysis pipeline)\n- 28 pytest tests (SQLite), ruff-clean\n- Multi-stage Dockerfile (non-root) + docker-compose (Postgres) + Makefile\n- \"Continue with RocketRide\" identity bridge: documented stub at\n  POST /api/v1/auth/rocketride (501)\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"66aa812ec9910f01b52bffc14612408c6b32ac1e","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/trees/66aa812ec9910f01b52bffc14612408c6b32ac1e"},"url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/commits/77314b542347d82d18f0dd17eda9802212a85ce2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/77314b542347d82d18f0dd17eda9802212a85ce2","node_id":"C_kwDOUHDBvtoAKDc3MzE0YjU0MjM0N2Q4MmQxOGYwZGQxN2VkYTk4MDIyMTJhODVjZTI","parents":[{"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/ce386b641f4319a4d9344a57c084f74d78902dbe","sha":"ce386b641f4319a4d9344a57c084f74d78902dbe","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/ce386b641f4319a4d9344a57c084f74d78902dbe"}],"sha":"77314b542347d82d18f0dd17eda9802212a85ce2","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/77314b542347d82d18f0dd17eda9802212a85ce2"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/ce386b641f4319a4d9344a57c084f74d78902dbe/comments","commit":{"author":{"date":"2026-08-29T06:59:53Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"comment_count":0,"committer":{"date":"2026-08-29T06:59:53Z","email":"ikundanpatil@gmail.com","name":"ikundanpatil"},"message":"FranchiseGuard AI — full 8-screen RocketRide Buildathon app\n\nMobile compliance app for franchise standards auditing (PS-18):\nsplash, login, home dashboard, upload inspection, AI analysis,\ncompliance report, location memory and manager alerts, plus\nInspections/Reports/Profile nav tabs.\n\n- React 18 + TypeScript strict, rsbuild Module Federation remote\n- Reusable component library: primitives, hand-built SVG charts,\n  vision bounding-box overlay, domain cards\n- Simulated vision/report engine in src/lib/ai.ts\n- Production-quality mock data: 15 stores, inspections, alerts, reports\n- Design tokens scoped to [data-fg-root]; blue/violet enterprise palette\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"49700843a7f7c2aaf0107565b6272a7411862d02","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/trees/49700843a7f7c2aaf0107565b6272a7411862d02"},"url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/git/commits/ce386b641f4319a4d9344a57c084f74d78902dbe","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/196650648?v=4","events_url":"https://api.github.com/users/ikundanpatil/events{/privacy}","followers_url":"https://api.github.com/users/ikundanpatil/followers","following_url":"https://api.github.com/users/ikundanpatil/following{/other_user}","gists_url":"https://api.github.com/users/ikundanpatil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ikundanpatil","id":196650648,"login":"ikundanpatil","node_id":"U_kgDOC7immA","organizations_url":"https://api.github.com/users/ikundanpatil/orgs","received_events_url":"https://api.github.com/users/ikundanpatil/received_events","repos_url":"https://api.github.com/users/ikundanpatil/repos","site_admin":false,"starred_url":"https://api.github.com/users/ikundanpatil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ikundanpatil/subscriptions","type":"User","url":"https://api.github.com/users/ikundanpatil","user_view_type":"public"},"html_url":"https://github.com/ikundanpatil/Franchise-Standards-Auditor/commit/ce386b641f4319a4d9344a57c084f74d78902dbe","node_id":"C_kwDOUHDBvtoAKGNlMzg2YjY0MWY0MzE5YTRkOTM0NGE1N2MwODRmNzRkNzg5MDJkYmU","parents":[],"sha":"ce386b641f4319a4d9344a57c084f74d78902dbe","url":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits/ce386b641f4319a4d9344a57c084f74d78902dbe"}],"requestUrl":"https://api.github.com/repos/ikundanpatil/Franchise-Standards-Auditor/commits?per_page=100&page=1&sha=433d13a26b224ff2a6f34c9cec0bf1c85a1b120a&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A19%3A35.228Z"}');
