 gap analysis lives in `warehouse-docs/executive/competitive-gaps.html`.","tree":{"sha":"5f86bb988700491efe16362d538a9ca0a6f87609","url":"https://api.github.com/repos/IQVO/labor-performance/git/trees/5f86bb988700491efe16362d538a9ca0a6f87609"},"url":"https://api.github.com/repos/IQVO/labor-performance/git/commits/746de5da588e7227b7ffe1c2f90f5348f88bd035","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/4073304?v=4","events_url":"https://api.github.com/users/claudioed/events{/privacy}","followers_url":"https://api.github.com/users/claudioed/followers","following_url":"https://api.github.com/users/claudioed/following{/other_user}","gists_url":"https://api.github.com/users/claudioed/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claudioed","id":4073304,"login":"claudioed","node_id":"MDQ6VXNlcjQwNzMzMDQ=","organizations_url":"https://api.github.com/users/claudioed/orgs","received_events_url":"https://api.github.com/users/claudioed/received_events","repos_url":"https://api.github.com/users/claudioed/repos","site_admin":false,"starred_url":"https://api.github.com/users/claudioed/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claudioed/subscriptions","type":"User","url":"https://api.github.com/users/claudioed","user_view_type":"public"},"html_url":"https://github.com/IQVO/labor-performance/commit/746de5da588e7227b7ffe1c2f90f5348f88bd035","node_id":"C_kwDOUIGXYtoAKDc0NmRlNWRhNTg4ZTcyMjdiN2ZmZTFjMmY5MGY1MzQ4Zjg4YmQwMzU","parents":[{"html_url":"https://github.com/IQVO/labor-performance/commit/2a9cde595538fd47d6808459de095892ee5791a2","sha":"2a9cde595538fd47d6808459de095892ee5791a2","url":"https://api.github.com/repos/IQVO/labor-performance/commits/2a9cde595538fd47d6808459de095892ee5791a2"}],"sha":"746de5da588e7227b7ffe1c2f90f5348f88bd035","url":"https://api.github.com/repos/IQVO/labor-performance/commits/746de5